class MeetingSchedule
  RULES = {
    weekly: ->(from) { from + 7 },
    first_thursday: ->(from) { MeetingSchedule.first_thursday(from.next_month) },
    every_two_weeks: ->(from) { from + 14 }
  }.freeze

  def self.first_thursday(date)
    day = date.beginning_of_month
    day += 1 until day.thursday?
    day
  end

  def next_meeting(from: Date.current, rule: :first_thursday)
    RULES.fetch(rule).call(from)
  end
end
